import pandas as pd
import os

files = ['ERP-2025-table10.xls', 'ERP-2025-table12.xls', 'CPI.xlsx']

for f in files:
    print(f"\n--- {f} ---")
    try:
        # Try reading with default engine first, then openpyxl or xlrd
        if f.endswith('.xls'):
            # Old excel format usually requires xlrd
            df = pd.read_excel(f, engine='xlrd', nrows=10)
        else:
            df = pd.read_excel(f, nrows=10)
        print(df)
    except Exception as e:
        print(f"Error reading {f}: {e}")

